mobileCSS:
/* ==================== STILI MOBILE PREMIUM CSC (solo sotto 1280px) ==================== */
@media (max-width: 1279px) {

  body {
    background:
      radial-gradient(circle at top left, rgba(34,211,238,0.07), transparent 30%),
      linear-gradient(180deg, #071019 0%, #0b1622 55%, #09131d 100%);
  }

  .header-row {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 30;
    background: transparent;
    pointer-events: none;
  }

  /* ================= TITLE PANEL ================= */

  .title-group {
    background:
      linear-gradient(180deg,
        rgba(16,24,36,0.94),
        rgba(10,18,28,0.92));

    border: 1px solid rgba(255,255,255,0.08);

    border-radius: 16px;

    padding: 13px 16px;

    max-width: 67%;

    box-shadow:
      0 10px 26px rgba(0,0,0,0.38),
      inset 0 1px 0 rgba(255,255,255,0.03);

    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);

    pointer-events: auto;

    cursor: grab;
    user-select: none;

    position: absolute;
    top: 18px;
    left: 18px;

    z-index: 50;
  }

  .title {
    font-size: 16px;
    line-height: 1.22;

    font-weight: 800;
    letter-spacing: -0.02em;

    color: #f8fafc;

    margin: 0;

    text-shadow: 0 2px 12px rgba(0,0,0,0.35);
  }

  .subtitle,
  .sources {
    display: none !important;
  }

  /* ================= ACTIONS ================= */

  .actions {
    display: flex;
    flex-direction: column;

    gap: 10px;

    align-items: flex-end;

    position: absolute;
    right: 14px;
    top: 14px;

    z-index: 40;

    pointer-events: auto;
  }

  .btn {
    position: relative;

    width: 52px;
    height: 52px;

    border-radius: 16px;

    border: 1px solid rgba(255,255,255,0.07);

    background:
      linear-gradient(180deg,
        rgba(18,28,40,0.96),
        rgba(10,18,28,0.94));

    color: #f8fafc;

    cursor: pointer;

    display: flex;
    align-items: center;
    justify-content: center;

    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);

    box-shadow:
      0 10px 24px rgba(0,0,0,0.35),
      inset 0 1px 0 rgba(255,255,255,0.03);

    transition:
      transform 0.18s ease,
      background 0.18s ease,
      border-color 0.18s ease,
      box-shadow 0.18s ease;
  }

  .btn:active {
    transform: scale(0.94);

    border-color: rgba(34,211,238,0.22);

    background:
      linear-gradient(180deg,
        rgba(34,211,238,0.10),
        rgba(10,18,28,0.96));

    box-shadow:
      0 6px 18px rgba(0,0,0,0.28),
      0 0 14px rgba(34,211,238,0.12);
  }

  .btn svg {
    width: 22px;
    height: 22px;

    fill: currentColor;
  }

  /* ================= NAV BUTTONS ================= */

  .btn.nav-btn {
    color: #22d3ee;
  }

  .btn.nav-btn svg {
    width: 26px;
    height: 26px;

    stroke: currentColor;
    stroke-width: 2.5;

    fill: none;
  }

  /* ================= CHART AREA ================= */

  #full-capture-area {
    display: flex;
    align-items: center;
    justify-content: center;

    padding-left: 8px;
    padding-right: 76px;

    overflow: hidden;
  }

  .chart-container {
    display: flex;
    justify-content: center;
    align-items: center;

    width: 100%;
    height: 100%;

    padding: 14px 0;
  }

  .chart-container img {
    width: auto;
    height: auto;

    max-width: 100%;
    max-height: 100%;

    object-fit: contain;

    border-radius: 14px;

    box-shadow:
      0 18px 40px rgba(0,0,0,0.42),
      0 0 0 1px rgba(255,255,255,0.03);
  }
}

@media (max-width: 1279px) and (hover: none) and (pointer: coarse) {
  #prev-btn,
  #next-btn {
    display: none !important;
  }
}
